preConditionHook:
// NO SUSTAINED PRIOR PENETRATION OF THE LEVEL THE BREAKOUT IS ABOUT TO CLEAR
// (G06-44): "penetrations of levels before the breakout usually seem to expend
// some of the energy behind the breakout, and often lead to poor trades".
// STATED IN THE PASSING SENSE so it ANDs into the pane -- the corpus's
// convention for every "do not trade while X" claim (PostGapFadeBlockWindow,
// FailedNewExtremeBlock) -- and the expected placement is NEGATED.
//
// The LONG reads the resistance the breakout is about to clear: the highest
// high of the levelLookback bars ENDING ONE BAR AGO, plus tolAtr ATRs (merge
// decision 7 -- the one-bar-shifted window extreme, tolerance always an ATR
// fraction, never ticks). The rule passes when the LONGEST RUN of CONSECUTIVE
// closes above that level anywhere in the last preLookback bars is at most
// maxBarsBeyond. Grimes forgives small failure-test probes, which
// maxBarsBeyond 2 does; what he does not forgive is a sustained excursion.
// Short mirrors on the support side.
//
// RUN LENGTH, NOT A COUNT AND NOT AN EVENT. Not TwiceFailedBreakoutAttempt,
// which COUNTS failed breakout EVENTS (a poke beyond a PER-CANDIDATE window
// extreme, and a close back inside) and reads them as a reason to expect the
// OTHER direction; this caps the LENGTH of any excursion beyond ONE level read
// once at bar 0. Not FailedNewExtremeBlock, a standing block also written
// positively but requiring a bear trend bar closing back through the level --
// an event test, not a run length. Three scattered single-bar pokes pass here
// and one three-bar excursion does not, which is the distinction the book
// draws.
//
// THE LEVEL IS READ ONCE, AT BAR 0, and every scanned bar is measured against
// that same level rather than against its own trailing window.
//
// THE LOOP IS GUARDED at preLookback >= 1 in the EL twin: EasyLanguage's For
// counts DOWN when the end value is below the start, so `for kk = 1 to 0`
// would execute at kk = 1 and kk = 0 and read the CURRENT bar, where this
// for-loop would not run at all. The guard makes the twins agree at every
// setting; the grid still starts at 1.
//
// SHIFT TEST: the level is a high plus an ATR multiple and every comparison is
// a close against it, so a constant added to the series moves both sides
// equally. maxBarsBeyond is compared against a COUNT.
//
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh mean:
// AtrProfitTarget's block verbatim, including the TWO separate accumulator
// statements and the re-seed when the length changes.
//
// The window scan mirrors EasyLanguage's Extremes(), which Highest()/Lowest()
// call: seeded at the window's first bar (offset 1), scanning the rest with a
// STRICT comparison so a tie keeps the earliest bar, under the EL relational
// tolerance -- hence el_gt / el_lt, as in Breakout.
//
// Every scratch value is a localVariables entry, never a hook-scope
// declaration, so the hooks survive a double placement.
//
// Deepest bar touched: max(preLookback, levelLookback, atrLookback + 1).
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (int aa = 0; aa < (int)atrLookback; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLookback;
} else {
    outIdx = (int)atrLookback;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLookback;
lvlHi = high[1];
lvlLo = low[1];
for (int i = 2; i <= (int)levelLookback; ++i) {
    if (el_gt(high[i], lvlHi)) lvlHi = high[i];
    if (el_lt(low[i], lvlLo)) lvlLo = low[i];
}
lvlHi = lvlHi + tolAtr * atrValue;
lvlLo = lvlLo - tolAtr * atrValue;
runHi = 0;
runLo = 0;
maxRunHi = 0;
maxRunLo = 0;
for (int kk = 1; kk <= (int)preLookback; ++kk) {
    if (el_gt(close[kk], lvlHi)) {
        runHi = runHi + 1;
        if (runHi > maxRunHi) maxRunHi = runHi;
    } else {
        runHi = 0;
    }
    if (el_lt(close[kk], lvlLo)) {
        runLo = runLo + 1;
        if (runLo > maxRunLo) maxRunLo = runLo;
    } else {
        runLo = 0;
    }
}
